Mp(a,b){return a+" \u0915\u094b "+b+" \u092e\u0947\u0902 \u092e\u0930\u094d\u091c \u0915\u0930\u0947\u0902?"},
Mr(a,b){return a+" \u0915\u094b "+b+" \u092e\u0947\u0902 \u092e\u0930\u094d\u091c \u0915\u0930 \u0926\u093f\u092f\u093e \u0917\u092f\u093e\u0964"},
gDb(){return"\u092c\u0948\u0915\u0905\u092a \u0914\u0930 \u0938\u093f\u0902\u0915"},
gPq(){return"\u0905\u092a\u0928\u093e \u0921\u0947\u091f\u093e \u0905\u092a\u0928\u0947 \u0916\u0941\u0926 \u0915\u0947 \u0917\u0942\u0917\u0932 \u0921\u094d\u0930\u093e\u0907\u0935 \u092e\u0947\u0902 \u0938\u0939\u0947\u091c\u0947\u0902"},
gPr(){return"\u0909\u0928 \u0928\u093e\u092e\u093f\u0924 \u0916\u093e\u0924\u094b\u0902 \u0915\u094b \u092a\u094d\u0930\u092c\u0902\u0927\u093f\u0924 \u0915\u0930\u0947\u0902 \u091c\u093f\u0928\u0915\u0947 \u0938\u093e\u0925 \u0906\u092a \u0935\u093e\u0938\u094d\u0924\u0935 \u092e\u0947\u0902 \u092c\u0948\u0902\u0915\u093f\u0902\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902"},
gPS(){return"\u0930\u094b\u091c\u093c\u092e\u0930\u094d\u0930\u093e \u0915\u0947 \u091b\u094b\u091f\u0947 \u0916\u0930\u094d\u091a\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u091b\u094b\u091f\u0940 \u0928\u0915\u0926 \u092b\u094d\u0932\u094b\u091f"},
gPn(){return"\u0916\u093e\u0924\u094b\u0902 \u0915\u0947 \u092c\u0940\u091a \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u0923"},
gPo(){return"\u0928\u0915\u0926, \u092c\u0948\u0902\u0915 \u0916\u093e\u0924\u094b\u0902, \u0914\u0930 \u0916\u0941\u0926\u0930\u093e \u0928\u0915\u0926 \u0915\u0947 \u092c\u0940\u091a \u092a\u0948\u0938\u093e \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u093f\u0924 \u0915\u0930\u0947\u0902"},
gPR(){return"\u090f\u0915 \u0905\u0935\u0927\u093f \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0924\u093e\u0915\u093f \u0909\u0938\u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u0941\u091b \u092d\u0940 \u092a\u094b\u0938\u094d\u091f \u092f\u093e \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0928 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0947"},
gPD(){return'"\u0935\u093f\u092d\u093e\u0917 \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0916\u0930\u094d\u091a" \u0930\u093f\u092a\u094b\u0930\u094d\u091f \u0915\u0947 \u0932\u093f\u090f \u0916\u0930\u094d\u091a\u094b\u0902 \u0915\u094b \u091f\u0948\u0917 \u0915\u0930\u0928\u0947 \u0939\u0947\u0924\u0941 \u0935\u093f\u092d\u093e\u0917'},
gPG(){return"\u0938\u092e\u092f \u0915\u0947 \u0938\u093e\u0925 \u0926\u0930\u0947\u0902 \u0932\u0949\u0917 \u0915\u0930\u0947\u0902 \u2014 \u0935\u093f\u0926\u0947\u0936\u0940 \u092e\u0941\u0926\u094d\u0930\u093e \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c\u094b\u0902 \u0915\u094b \u0938\u094d\u0935\u0924\u0903 \u092d\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 \u092a\u0941\u0928\u0930\u094d\u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0924\u093e \u0939\u0948"},
gPQ(){return"\u0924\u0930\u093e\u091c\u093c\u0942 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0928\u0915\u0926, \u0907\u0915\u094d\u0935\u093f\u091f\u0940, \u0914\u0930 \u0905\u0928\u094d\u092f \u0916\u093e\u0924\u0947 \u0915\u0939\u093e\u0902 \u0925\u0947"},
gPA(){return"\u0915\u0902\u092a\u0928\u0940 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932"},
gPC(){return"\u0928\u093e\u092e, \u0932\u094b\u0917\u094b, \u0938\u0902\u092a\u0930\u094d\u0915 \u0935\u093f\u0935\u0930\u0923, \u0914\u0930 \u091a\u093e\u0932\u093e\u0928 \u0928\u0902\u092c\u0930\u093f\u0902\u0917 \u092a\u094d\u0930\u0940\u092b\u093c\u093f\u0915\u094d\u0938"},
gPE(){return"\u0938\u094d\u091f\u0949\u0915, \u0932\u0947\u091c\u0930, \u0914\u0930 \u0916\u093e\u0924\u093e \u0915\u094b\u0921 \u0915\u0940 \u0938\u094d\u0925\u093f\u0930\u0924\u093e \u091c\u093e\u0902\u091a\u0947\u0902 \u2014 \u0914\u0930 \u091c\u094b \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0930\u0942\u092a \u0938\u0947 \u0920\u0940\u0915 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948 \u0909\u0938\u0915\u0940 \u092e\u0930\u092e\u094d\u092e\u0924 \u0915\u0930\u0947\u0902"},
gPp(){return"\u0915\u093f\u0938\u0928\u0947 \u0915\u094d\u092f\u093e \u0915\u093f\u092f\u093e \u2014 \u091a\u093e\u0932\u093e\u0928, \u092d\u0941\u0917\u0924\u093e\u0928, \u0935\u093e\u0909\u091a\u0930, \u0905\u0935\u0927\u093f \u0932\u0949\u0915, \u0914\u0930 \u0916\u093e\u0924\u093e \u092a\u0930\u093f\u0935\u0930\u094d\u0924\u0928"},
gPF(){return"\u0935\u0947\u0924\u0928, \u0905\u0917\u094d\u0930\u093f\u092e, \u0914\u0930 \u092e\u093e\u0938\u093f\u0915 \u092a\u0947\u0930\u094b\u0932"},
gPP(){return"\u0917\u0932\u0924\u0940 \u0938\u0947 \u0926\u094b \u092c\u093e\u0930 \u0926\u0930\u094d\u091c \u0915\u093f\u090f \u0917\u090f \u0926\u094b \u0917\u094d\u0930\u093e\u0939\u0915 \u092f\u093e \u0906\u092a\u0942\u0930\u094d\u0924\u093f\u0915\u0930\u094d\u0924\u093e \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0915\u094b \u092e\u093f\u0932\u093e\u090f\u0902"},
gPL(){return"\u0938\u094d\u0925\u093f\u0930 \u0938\u0902\u092a\u0924\u094d\u0924\u093f"},
gPM(){return"\u0935\u093e\u0939\u0928, \u0909\u092a\u0915\u0930\u0923, \u092b\u0930\u094d\u0928\u0940\u091a\u0930 \u2014 \u092e\u0942\u0932\u094d\u092f\u0939\u094d\u0930\u093e\u0938 \u0938\u0939\u093f\u0924"},
gPu(){return"\u0936\u093e\u0916\u093e\u090f\u0902 \u0914\u0930 \u0917\u094b\u0926\u093e\u092e"},
gPw(){return"\u090f\u0915\u0932 \u0938\u094d\u0925\u093e\u0928 \u2014 \u092e\u0932\u094d\u091f\u0940-\u092c\u094d\u0930\u093e\u0902\u091a \u092e\u094b\u0921 \u0905\u0928\u0932\u0949\u0915 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092f\u0939\u093e\u0902 \u090f\u0915 \u0936\u093e\u0916\u093e \u091c\u094b\u0921\u093c\u0947\u0902"},
gPv(){return"\u0938\u094d\u0925\u093e\u0928 \u0914\u0930 \u0917\u094b\u0926\u093e\u092e \u092a\u094d\u0930\u092c\u0902\u0927\u093f\u0924 \u0915\u0930\u0947\u0902"},
gTM(){return"\u092c\u0948\u0915\u0905\u092a \u0914\u0930 \u0938\u093f\u0902\u0915 \u0915\u0947 \u0932\u093f\u090f \u0938\u0940\u0927\u0940 \u092b\u093c\u093e\u0907\u0932 \u092a\u0939\u0941\u0902\u091a \u091a\u093e\u0939\u093f\u090f \u0914\u0930 \u092f\u0939 \u0905\u092d\u0940 \u0935\u0947\u092c \u092c\u093f\u0932\u094d\u0921 \u092e\u0947\u0902 \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0907\u0938\u0915\u0947 \u0932\u093f\u090f \u092e\u094b\u092c\u093e\u0907\u0932 \u092f\u093e \u0921\u0947\u0938\u094d\u0915\u091f\u0949\u092a \u0910\u092a \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964"},
gVT(){return"\u0915\u0902\u092a\u0928\u0940 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932"},
