gVn(){return"\u092a\u0924\u093e \u2014 \u0939\u0930 \u091a\u093e\u0932\u093e\u0928 \u092a\u0930 \u091b\u092a\u0924\u093e \u0939\u0948"},
gVm(){return"\u0907\u0938\u0947 \u090f\u0915 \u092c\u093e\u0930 \u092d\u0930\u0947\u0902 \u2014 \u092f\u0939 \u0928\u092e\u0942\u0928\u093e \u0932\u0947\u0906\u0909\u091f \u0915\u0940 \u0924\u0930\u0939 \u0939\u0940 \u0939\u0930 \u091a\u093e\u0932\u093e\u0928 \u092a\u0930 \u091b\u092a\u0924\u093e \u0939\u0948 (\u0938\u0902\u092a\u0930\u094d\u0915 \u0935\u094d\u092f\u0915\u094d\u0924\u093f, \u092d\u0935\u0928/\u0938\u0921\u093c\u0915/\u0915\u094d\u0937\u0947\u0924\u094d\u0930, \u092a\u0940\u0913 \u092c\u0949\u0915\u094d\u0938, \u0936\u0939\u0930, \u0926\u0947\u0936)\u0964"},
gVt(){return"\u092c\u0947\u0938 \u0915\u0930\u0947\u0902\u0938\u0940"},
gVr(){return"\u0939\u0930 \u0930\u093f\u092a\u094b\u0930\u094d\u091f \u0914\u0930 \u0928\u092f\u093e \u0917\u094d\u0930\u093e\u0939\u0915/\u091a\u093e\u0932\u093e\u0928 \u0907\u0938 \u092a\u0930 \u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f \u0939\u094b\u0924\u093e \u0939\u0948\u0964 \u0907\u0938\u0947 \u092c\u0926\u0932\u0928\u0947 \u0938\u0947 \u0910\u0924\u093f\u0939\u093e\u0938\u093f\u0915 \u0906\u0902\u0915\u0921\u093c\u0947 \u092a\u0942\u0930\u094d\u0935\u0935\u094d\u092f\u093e\u092a\u0940 \u0930\u0942\u092a \u0938\u0947 \u092a\u0930\u093f\u0935\u0930\u094d\u0924\u093f\u0924 \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u0947 \u2014 \u0935\u0947 \u091c\u093f\u0938 \u092e\u0941\u0926\u094d\u0930\u093e \u092e\u0947\u0902 \u092a\u094b\u0938\u094d\u091f \u0915\u093f\u090f \u0917\u090f \u0925\u0947 \u0909\u0938\u0940 \u092e\u0947\u0902 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964"},
gVF(){return"\u091a\u093e\u0932\u093e\u0928 \u0928\u0902\u092c\u0930\u093f\u0902\u0917"},
gVp(){return"\u092c\u0948\u0902\u0915 \u0935\u093f\u0935\u0930\u0923 \u2014 \u0939\u0930 \u091a\u093e\u0932\u093e\u0928 \u092a\u0930 \u091b\u092a\u0924\u093e \u0939\u0948"},
gVo(){return"\u092e\u0941\u0926\u094d\u0930\u093f\u0924 \u091a\u093e\u0932\u093e\u0928\u094b\u0902 \u092a\u0930 \u092c\u0948\u0902\u0915 \u0935\u093f\u0935\u0930\u0923 \u092c\u0949\u0915\u094d\u0938 \u0915\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u091b\u093f\u092a\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0907\u0938\u0947 \u0916\u093e\u0932\u0940 \u091b\u094b\u0921\u093c\u0947\u0902\u0964"},
gVy(){return"\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u0915\u093e \u0938\u094d\u0935\u0930\u0942\u092a"},
gVx(){return"\u0939\u0930 \u092e\u0941\u0926\u094d\u0930\u093f\u0924 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092a\u0930 \u0932\u093e\u0917\u0942 \u0939\u094b\u0924\u093e \u0939\u0948 \u2014 \u091a\u093e\u0932\u093e\u0928, \u0915\u094b\u091f\u0947\u0936\u0928, \u0916\u0930\u0940\u0926 \u0906\u0926\u0947\u0936\u0964"},
gVL(){return"\u0930\u093e\u0936\u093f \u0915\u094b \u0936\u092c\u094d\u0926\u094b\u0902 \u092e\u0947\u0902 \u0926\u093f\u0916\u093e\u090f\u0902"},
gVM(){return"\u092c\u0948\u0902\u0915 \u0935\u093f\u0935\u0930\u0923 \u092c\u0949\u0915\u094d\u0938 \u0926\u093f\u0916\u093e\u090f\u0902"},
