ga30(){return"\u092b\u0902\u0921 \u092c\u0928\u093e\u090f\u0902"},
ga38(){return"\u0915\u094b\u0908 \u0915\u0938\u094d\u091f\u094b\u0921\u093f\u092f\u0928 \u0928\u093f\u092f\u0941\u0915\u094d\u0924 \u0928\u0939\u0940\u0902"},
ga2Z(){return"\u0936\u0947\u0937 \u0930\u093e\u0936\u093f"},
